import { chapters, chapterHTML, references } from './content.js';
import { initDemos, activateDemo } from './demos.js';
const main=document.getElementById('main');
main.insertAdjacentHTML('beforeend',chapters.slice(1).map((c,i)=>chapterHTML(c,i+1)).join('')+`<footer class="document-footer"><img src="assets/mathconcept-logo.png" alt="MathConcept"><div><strong>The connected curriculum</strong><p>First draft · 22 September 2026</p></div><a href="#vision">Back to the beginning ↑</a></footer>`);
const nav=document.getElementById('chapters');
nav.innerHTML=chapters.map((c,i)=>`<a href="#${c.id}" data-index="${i}"><span>${String(i+1).padStart(2,'0')}</span>${c.title}</a>`).join('')+`<div class="nav-references"><span>REFERENCE</span><button data-action="reference" data-ref="scope">Detailed scope ↗</button><button data-action="reference" data-ref="technical">Technical approach ↗</button><button data-action="reference" data-ref="assumptions">Open decisions ↗</button></div>`;
const sections=[...document.querySelectorAll('.chapter')];
let current=0,present=false,toastTimer;
const dialog=document.getElementById('detail-dialog');
export function openDialog(title,body,className=''){dialog.className=className;document.getElementById('dialog-title').textContent=title;document.getElementById('dialog-body').innerHTML=body;if(!dialog.open)dialog.showModal();dialog.scrollTop=0}
function notify(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4200)}
function update(index){current=Math.max(0,Math.min(chapters.length-1,index));sections.forEach((s,i)=>s.classList.toggle('current',i===current));nav.querySelectorAll('a').forEach((a,i)=>{a.classList.toggle('active',i===current);if(i===current)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')});document.getElementById('chapter-label').textContent=chapters[current].title;document.getElementById('slide-counter').textContent=`${String(current+1).padStart(2,'0')} / ${chapters.length}`;document.getElementById('prev').disabled=current===0;document.getElementById('next').disabled=current===chapters.length-1;document.title=`MathConcept — ${chapters[current].title}`;activateDemo(chapters[current].id)}
function go(index){const i=Math.max(0,Math.min(chapters.length-1,index));update(i);history.replaceState(null,'','#'+chapters[i].id);if(present)window.scrollTo({top:0,behavior:'instant'});else sections[i].scrollIntoView({behavior:'instant',block:'start'})}
function toggleMode(){present=!present;document.body.classList.toggle('present-mode',present);document.getElementById('mode').innerHTML=present?'Read <span>↙</span>':'Present <span>↗</span>';document.getElementById('mode').setAttribute('aria-pressed',present);document.getElementById('presentation-footer').hidden=!present;go(current)}
document.getElementById('menu').addEventListener('click',()=>{const open=document.getElementById('sidebar').classList.toggle('open');document.getElementById('menu').setAttribute('aria-expanded',open)});
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#"]');if(link){const i=chapters.findIndex(c=>'#'+c.id===link.getAttribute('href'));if(i>=0){e.preventDefault();go(i);document.getElementById('sidebar').classList.remove('open');document.getElementById('menu').setAttribute('aria-expanded','false')}}const b=e.target.closest('[data-action="reference"]');if(b){const r=references[b.dataset.ref];openDialog(r.title,r.body)}});
document.getElementById('mode').addEventListener('click',toggleMode);
document.getElementById('prev').addEventListener('click',()=>go(current-1));document.getElementById('next').addEventListener('click',()=>go(current+1));
document.getElementById('close-dialog').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.getElementById('references').addEventListener('click',()=>openDialog('Reference documents',`<p class="reference-lead">Read the details behind the proposal.</p><div class="reference-menu">${Object.entries(references).map(([k,v])=>`<button data-action="reference" data-ref="${k}"><strong>${v.title}</strong><span>→</span></button>`).join('')}</div><p class="small">The embedded screens use the existing demo in a separate proposal session. Payment checks are simulated; no real payment or message is sent.</p>`));
window.addEventListener('hashchange',()=>{const i=chapters.findIndex(c=>c.id===location.hash.slice(1));if(i>=0)go(i)});
window.addEventListener('keydown',e=>{if(document.body.classList.contains('demo-expanded')||dialog.open||e.target.matches('input,textarea,select,button,[contenteditable]'))return;if(present&&['ArrowRight','PageDown'].includes(e.key)){e.preventDefault();go(current+1)}if(present&&['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(current-1)}if(e.key.toLowerCase()==='p'&&!e.ctrlKey&&!e.metaKey&&!e.altKey)toggleMode()});
let scrollQueued=false;window.addEventListener('scroll',()=>{if(present||scrollQueued)return;scrollQueued=true;requestAnimationFrame(()=>{scrollQueued=false;if(present||document.body.classList.contains('demo-expanded'))return;let index=0;sections.forEach((s,i)=>{if(s.getClientRects().length&&s.getBoundingClientRect().top<window.innerHeight*.35)index=i});if(index!==current)update(index)})},{passive:true});
initDemos({notify,openDialog});
const initial=chapters.findIndex(c=>c.id===location.hash.slice(1));update(Math.max(0,initial));if(initial>0)requestAnimationFrame(()=>sections[initial].scrollIntoView({behavior:'instant'}));
